--1.资产
--标的类金融产品
delete from FIN_PRODUCT ;
--交易类金融产品
delete from FIN_TRADE_PRODUCT;
--金融产品分类
delete from FIN_PRODUCT_TYPE where FINPROD_ID not in (select FINPROD_ID from FIN_PRODUCT UNION ALL select FINPROD_ID from FIN_TRADE_PRODUCT);
--开放计划
--delete from FIN_OPEN_PLAN where FINPROD_ID not in (select FINPROD_ID from FIN_PRODUCT UNION ALL select FINPROD_ID from FIN_TRADE_PRODUCT);
--标的类金融产品扩展
delete from FIN_PRODUCT_EXT where FINPROD_ID not in (select FINPROD_ID from FIN_PRODUCT UNION ALL select FINPROD_ID from FIN_TRADE_PRODUCT);
--现金流
delete from FIN_CASH_INFO where FINPROD_ID not in (select FINPROD_ID from FIN_PRODUCT UNION ALL select FINPROD_ID from FIN_TRADE_PRODUCT);
--现金流计划
delete from FIN_CASH_PLAN where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--现金流支付规则
delete from FIN_CASH_PAY_RULE where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--现金流计算规则
delete from FIN_CASH_CALC_RULE where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--业绩报酬计提规则
--delete from FIN_FLOAT_COUNTING_RULE where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--业绩报酬计提计划
--delete from FIN_PERF_REWARD_ACCRSCHE where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--业绩报酬计算规则
--delete from FIN_FLOAT_CALC_RULE where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);
--业绩报酬计算规则明细
--delete from FIN_FLOAT_CALC_RULE_DETAIL where CASH_ID not in (select CASH_ID from FIN_CASH_INFO);

--2.交易
--金融产品交易
DELETE FROM TRD_PRODUCT_DEAL;
--交易扩展表
DELETE FROM TRD_PRODUCT_DEAL_EXT;
--交易费用明细表
DELETE FROM TG_TRADE_FEE_DETAIL;
--入账信息表 
DELETE FROM BOK_DEAL_ACCOUNTING WHERE BUSI_NO NOT IN (SELECT TRADE_ID FROM TRD_VOUCH_DEAL);
--入账账务明细表
DELETE FROM BOK_DEAL_ACCOUNTING_DETAIL WHERE BUSI_TYPE != '23';
--结算指令表
DELETE FROM STL_ORDERS;
--结算指令扩展表 
DELETE FROM STL_ORDERS_EXT;
--账务明细代码
DELETE FROM BOK_DETAIL_ID WHERE (BOOKSET_ID,BOK_DETAIL_ID)
NOT IN (SELECT B.BOOKSET_ID,B.BOK_DETAIL_ID FROM BOK_BOOKDETAIL_ALL B
WHERE B.BOOK_TYPE = '03');


--账套
--账套
delete bok_bookset x where x.bookset_id not in(select  a.bookset_id from bok_bookset a where a.bookset_type ='01');
--账套日期
delete bok_bookset_date x where x.bookset_id not in(select  a.bookset_id from bok_bookset a where a.bookset_type ='01');
--账套扩展表
delete bok_bookset_ext x where x.bookset_id not in(select  a.bookset_id from bok_bookset a where a.bookset_type ='01');


